  "por": "par",
  "La GTS es un banco online de futbolistas: dejas una copia repetida pidiendo otro futbolista a cambio, y cualquiera que tenga el que pides puede cambiártelo aunque no estés conectado.": "La GTS est une banque de joueurs en ligne : tu déposes une copie en double en demandant un autre joueur en échange, et n'importe qui possédant celui que tu demandes peut faire l'échange même si tu n'es pas connecté.",
  "Para usarla tienes que entrar con tu cuenta.": "Pour l'utiliser, tu dois te connecter avec ton compte.",
  "Ir a Perfil para entrar": "Aller au Profil pour se connecter",
  "Recuperar": "Récupérer",
  "Dejar un futbolista": "Déposer un joueur",
  "Solo copias repetidas": "Copies en double uniquement",
  "Mejora la «Ventanilla GTS» en Mejoras": "Améliore le « Guichet GTS » dans Améliorations",
  "Huecos: {openLength}/{slots}. La copia que dejas va sin entrenamiento, estrellas ni ascensión: tu futbolista se queda con todo. Un HÉROE ascendido sí puede dejar sus copias repetidas. No se pueden dejar Leyenda ni futbolistas de evento, ni repetir un cambio.": "Emplacements : {openLength}/{slots}. La copie que tu déposes part sans entraînement, étoiles ni ascension : ton joueur garde tout. Un HÉROS ascensionné peut déposer ses copies en double. Impossible de déposer des Légendes ou des joueurs d'événement, ou de répéter un échange.",
  "Buscar futbolista (el que quieres o el que piden)": "Rechercher un joueur (celui que tu veux ou celui demandé)",
