  "Deja una copia repetida, pide el futbolista que te falta y recoge tu cambio cuando vuelvas.": "Dépose une copie en double, demande le joueur qui te manque et récupère ton échange à ton retour.",
  "Ese depósito ya no está: puede que alguien te lo acabe de cambiar.": "Ce dépôt n'existe plus : quelqu'un vient peut-être de l'échanger.",
