  "Cuenta online": "Compte en ligne",
  "El servicio online no está activado en esta versión. Tu progreso se guarda en este navegador (Ajustes » Exportar/Importar para llevarlo a otro). Con el servicio activo podrás entrar con Google, reservar tu nombre en todo el mundo, aparecer en el ranking global y guardar en la nube.": "Le service en ligne n'est pas activé dans cette version. Ta progression est sauvegardée dans ce navigateur (Paramètres » Exporter/Importer pour l'emporter ailleurs). Avec le service actif, tu pourras te connecter avec Google, réserver ton nom dans le monde entier, apparaître dans le classement mondial et sauvegarder dans le cloud.",
  "Estás jugando como invitado: tu progreso se guarda solo en este navegador. Entra con Google para reservar tu nombre en todo el mundo, aparecer en el ranking y guardar en la nube. Tu correo es privado: nunca aparece en el ranking.": "Tu joues en invité : ta progression n'est sauvegardée que dans ce navigateur. Connecte-toi avec Google pour réserver ton nom dans le monde entier, apparaître dans le classement et sauvegarder dans le cloud. Ton e-mail est privé : il n'apparaît jamais dans le classement.",
  "Nombre global: <b>{onlineName}</b> (permanente)": "Nom mondial : <b>{onlineName}</b> (définitif)",
  "Reserva tu nombre global. Si «{profileName}» ya está ocupado, elige otro: tu progreso no se toca.": "Réserve ton nom mondial. Si « {profileName} » est déjà pris, choisis-en un autre : ta progression n'est pas touchée.",
