  "Las llaves y los niveles son de esta temporada: cuando termine, empieza una nueva con su propio pase. La EXP cuenta aunque no tengas llave: al abrir una fila puedes reclamar todo lo que ya hayas alcanzado.": "Les clés et les niveaux sont propres à cette saison : quand elle se termine, une nouvelle commence avec son propre passe. L'EXP compte même sans clé : en ouvrant une ligne, tu peux réclamer tout ce que tu as déjà atteint.",
