  "✦ DEL AURA": "✦ DE L'AURA",
  "Tienes <b>5 equipos</b>: cambia entre ellos arriba. Elige <b>7 candidatos</b>. Empiezas solo con el <b>capitán</b>; al subir de nivel podrás fichar a los otros seis (máximo {MAX_TEAM} en el campo). Pulsa un futbolista de tu colección para añadirlo o quitarlo, pulsa una plaza para cambiarla, o arrastra para colocar e intercambiar. Se guarda solo.": "Tu as <b>5 équipes</b> : passe de l'une à l'autre en haut. Choisis <b>7 candidats</b>. Tu commences avec le <b>capitaine</b> seul ; en montant de niveau, tu pourras recruter les six autres ({MAX_TEAM} maximum sur le terrain). Appuie sur un joueur de ta collection pour l'ajouter ou le retirer, appuie sur une place pour la changer, ou fais glisser pour placer et échanger. La sauvegarde est automatique.",
