  "¡RECLAMAR!": "RÉCLAMER !",
  "Elige el uniforme de tu escuadra: cambia el cuerpo y conserva la cabeza original y todas las animaciones. Se consiguen con las recompensas de equipo de la Enciclopedia.": "Choisis la tenue de ton escouade : elle change le corps et garde la tête d'origine et toutes les animations. Elles s'obtiennent avec les récompenses d'équipe de l'Encyclopédie.",
