  "Fichas de entrenamiento: <b>{have}</b>": "Jetons d'entraînement : <b>{have}</b>",
  "Devolver puntos": "Rendre les points",
  "Cada ficha suma 1 punto a la estadística que elijas (máximo {tmax} para este futbolista). Se ganan con victorias, rangos superados, supervivencia infinita, misiones semanales y logros.": "Chaque jeton ajoute 1 point à la statistique de ton choix ({tmax} maximum pour ce joueur). Ils se gagnent avec les victoires, les rangs franchis, la survie infinie, les missions hebdomadaires et les succès.",
  "Técnica de HÉROE:": "Technique de HÉROS :",
  "Pasiva:": "Passif :",
  "(adaptación de InaZurvivors)": "(adaptation InaZurvivors)",
  "Talento:": "Talent :",
  "(efecto adaptado; sube con el nivel de la técnica)": "(effet adapté ; il augmente avec le niveau de la technique)",
  "Repertorio (2 técnicas activas en combate)": "Répertoire (2 techniques actives en combat)",
  "☆ Empezar con esta": "☆ Commencer avec celle-ci",
  "✦ Ver su Aura": "✦ Voir son Aura",
  "{add} Aura": "{add} Aura",
  "Valores centrados en 60: por encima suman, por debajo restan. Cada técnica usa las estadísticas de su futbolista. Lo propio llega a 99; con un Aura, hasta {EFFECTIVE_STAT_MAX}.": "Valeurs centrées sur 60 : au-dessus elles ajoutent, en dessous elles retirent. Chaque technique utilise les statistiques de son joueur. Les stats propres vont jusqu'à 99 ; avec une Aura, jusqu'à {EFFECTIVE_STAT_MAX}.",
  "Banner de agradecimiento": "Bannière de remerciement",
  "Ataque a los Titanes, Los Siete Pecados Capitales y Axel Encapuchado · {cost} fichas de evento la tirada": "L'Attaque des Titans, Seven Deadly Sins et Axel Encapuchonné · {cost} jetons d'événement le tirage",
