  "NUEVO": "NOUVEAU",
  ": se desbloquea para siempre y ya puede ir en Mi Equipo.": " : débloqué pour toujours, il peut maintenant aller dans Mon Équipe.",
  "Duplicado": "Doublon",
  ": sirve para ascender al futbolista; si ya no puede ascender más, se convierte en monedas.": " : il sert à l'ascension du joueur ; s'il ne peut plus monter, il se transforme en pièces.",
  "Los duplicados también pagan la <b>ascensión</b> de cualquier futbolista (Fix 1.53): cada ascensión sube una rareza y cuesta según la rareza desde la que sube (Común {ascenso}, Raro {ascenso2}, Épico {ascenso3}, Legendario {ascenso4}). Al llegar a Mítico, el HÉROE cuesta según la rareza con la que nació: Común {heroe}, Raro {heroe2}, Épico {heroe3}, Legendario {heroe4}, Mítico {heroe5} y Leyenda {heroe6}. Después, cada HÉROE gana hasta {HERO_STARS_MAX} estrellas de héroe (Mítico {estrella} duplicados cada una).": "Les doublons paient aussi l'<b>ascension</b> de n'importe quel joueur : chaque ascension fait monter d'une rareté et coûte selon la rareté de départ (Commun {ascenso}, Rare {ascenso2}, Épique {ascenso3}, Légendaire {ascenso4}). Une fois Mythique, le HÉROS coûte selon la rareté d'origine : Commun {heroe}, Rare {heroe2}, Épique {heroe3}, Légendaire {heroe4}, Mythique {heroe5} et Légende {heroe6}. Ensuite, chaque HÉROS gagne jusqu'à {HERO_STARS_MAX} étoiles de héros (Mythique : {estrella} doublons chacune).",
  "Con {MAX_STARS} estrellas y HÉROE, cada copia da monedas (de {comun} a {leyenda} según la rareza).": "Avec {MAX_STARS} étoiles et HÉROS, chaque copie donne des pièces (de {comun} à {leyenda} selon la rareté).",
  "Fichas = máquina de cápsulas · Monedas = mejoras y tiendas. Gráficos de la máquina: Inazuma Eleven 3 (hoja de The Spriters Resource, ripeada por Avegaille), recurso local.": "Jetons = machine à capsules · Pièces = améliorations et boutiques. Graphismes de la machine : Inazuma Eleven 3 (planche de The Spriters Resource, extraite par Avegaille), ressource locale.",
  "Duplicado · +{refund} monedas": "Doublon · +{refund} pièces",
  "¡Estrella {starReady} lista! Súbela en su ficha": "Étoile {starReady} prête ! Monte-la sur sa fiche",
