  "Por comprar": "Pas encore achetées",
  "REPERTORIO": "RÉPERTOIRE",
  "Cada futbolista solo usa su propio repertorio. Aquí desbloqueas sus técnicas y compras <b>manuales</b> de daño permanente (subir de nivel una técnica en partida es aparte).": "Chaque joueur n'utilise que son propre répertoire. Ici, tu débloques ses techniques et tu achètes des <b>manuels</b> de dégâts permanents (monter une technique de niveau pendant la partie, c'est à part).",
  "Bonificaciones para todo el equipo. No cambian la equipación Raimon que se ve en combate.": "Bonus pour toute l'équipe. Ils ne changent pas la tenue Raimon visible en combat.",
  "InaZurvivors — Proyecto de fans no oficial": "InaZurvivors — Projet de fans non officiel",
  "InaZurvivors es un fangame independiente y gratuito desarrollado por AstraStorm17, inspirado en la franquicia Inazuma Eleven.": "InaZurvivors est un fangame indépendant et gratuit développé par AstraStorm17, inspiré de la franchise Inazuma Eleven.",
  "Inazuma Eleven, sus personajes, nombres, diseños, logotipos, música y materiales originales son propiedad de LEVEL-5 y/o sus respectivos titulares.": "Inazuma Eleven, ses personnages, noms, designs, logos, musiques et matériaux originaux sont la propriété de LEVEL-5 et/ou de leurs détenteurs respectifs.",
  "Este proyecto no está afiliado, patrocinado ni aprobado por LEVEL-5.": "Ce projet n'est ni affilié, ni sponsorisé, ni approuvé par LEVEL-5.",
  "El código y los materiales originales desarrollados específicamente para InaZurvivors pertenecen a sus respectivos autores.": "Le code et les matériaux originaux développés spécifiquement pour InaZurvivors appartiennent à leurs auteurs respectifs.",
  "Los recursos gráficos y sonoros de terceros conservan sus derechos originales.": "Les ressources graphiques et sonores de tiers conservent leurs droits d'origine.",
  "La inclusión de créditos y este aviso no implica la existencia de una licencia o autorización para distribuir material protegido.": "La présence de crédits et de cet avis n'implique l'existence d'aucune licence ni autorisation de distribuer du matériel protégé.",
  "Desarrollo": "Développement",
  "Diseño, dirección y desarrollo: AstraStorm17.": "Conception, direction et développement : AstraStorm17.",
  "Programación con asistencia de Claude (Anthropic).": "Programmation assistée par Claude (Anthropic).",
  "Recursos de terceros y su procedencia": "Ressources de tiers et leur provenance",
  "Futbolistas, retratos, cuerpos, escudos, objetos, arenas y música: Inazuma Eleven 2 (LEVEL-5), extraídos de una copia propia del juego.": "Joueurs, portraits, corps, écussons, objets, arènes et musique : Inazuma Eleven 2 (LEVEL-5), extraits d'une copie personnelle du jeu.",
  "Futbolistas, retratos y escudos de las sagas Mundial, GO, Chrono Stones, Galaxy, Ares y Orion: Inazuma Eleven 3 (LEVEL-5) con el parche de fans «Great Road of Heroes 3.1». Autoría del parche: no verificada; base y añadidos del parche no se pueden separar.": "Joueurs, portraits et écussons des sagas Mondial, GO, Chrono Stones, Galaxy, Ares et Orion : Inazuma Eleven 3 (LEVEL-5) avec le patch de fans « Great Road of Heroes 3.1 ». Auteur du patch : non vérifié ; la base et les ajouts du patch ne peuvent pas être séparés.",
  "Creados para InaZurvivors: efectos de supertécnicas, efectos de sonido, iconos de elemento, orbes, música «Generada» e interfaz.": "Créés pour InaZurvivors : effets des supertechniques, effets sonores, icônes d'élément, orbes, musique « Générée » et interface.",
  "Redes sociales": "Réseaux sociaux",
  "Sobre el desarrollador": "À propos du développeur",
  "AstraStorm también ha creado otros videojuegos.": "AstraStorm a aussi créé d'autres jeux vidéo.",
  "Enlaces oficiales": "Liens officiels",
  "Sin cuenta, InaZurvivors no recopila datos personales: tu progreso se guarda solo en este navegador. Con cuenta online (Google) se guardan tu correo de Google (privado), tu nombre, tus marcas y tu guardado.": "Sans compte, InaZurvivors ne collecte aucune donnée personnelle : ta progression n'est sauvegardée que dans ce navigateur. Avec un compte en ligne (Google), ton e-mail Google (privé), ton nom, tes records et ta sauvegarde sont conservés.",
  "{VERSION_LABEL} · compilación interna {BUILD}": "{VERSION_LABEL} · build interne {BUILD}",
