  "Compartir mis partidas": "Partager mes parties",
  "Con la sesión iniciada, cada partida en solitario se graba (posiciones, técnicas y cartas, sin nada personal) para que el autor vea cómo se juega y equilibre el juego. Se guardan tus 3 últimas y las de tus marcas del ranking.": "Quand tu es connecté, chaque partie en solo est enregistrée (positions, techniques et cartes, rien de personnel) pour que l'auteur voie comment on joue et équilibre le jeu. Tes 3 dernières et celles de tes records du classement sont conservées.",
