  "¿Seguro? {teamLabel} será tu equipo favorito para siempre. Elígelo otra vez para confirmar.": "Sûr ? {teamLabel} sera ton équipe préférée pour toujours. Choisis-la à nouveau pour confirmer.",
  "{active}/{TRAIN_SLOTS} técnicas activas": "{active}/{TRAIN_SLOTS} techniques actives",
  "Prueba las técnicas de tus futbolistas al nivel que quieras, también las combinadas que puedan hacer juntos (con sus Auras incluidas). Nadie recibe daño y no se gana nada: ni recompensas, ni misiones, ni ranking.": "Essaie les techniques de tes joueurs au niveau que tu veux, y compris les combinées qu'ils peuvent faire ensemble (Auras comprises). Personne ne subit de dégâts et on ne gagne rien : ni récompenses, ni missions, ni classement.",
