  "Elige a quién echas del equipo. Pierdes sus técnicas y su parte de la vida, y su hueco queda libre para otro fichaje. El capitán no se puede echar.": "Choisis qui tu renvoies de l'équipe. Tu perds ses techniques et sa part de vie, et sa place se libère pour une autre recrue. Le capitaine ne peut pas être renvoyé.",
