  "Aguanta las oleadas de rivales hasta que llegue el jefe y derrótalo. Solo tu capitán recibe daño: si su vida llega a cero, pierdes (pero te quedas las monedas).": "Résiste aux vagues d'adversaires jusqu'à l'arrivée du boss et bats-le. Seul ton capitaine subit des dégâts : si sa vie tombe à zéro, tu perds (mais tu gardes les pièces).",
