  "OBJETO": "OBJET",
  "Tiro, regate, defensa y parada atacan solos; los talentos son pasivos. Mejóralas hasta nivel 10 y evolucionan.": "Tir, dribble, défense et arrêt attaquent tout seuls ; les talents sont passifs. Améliore-les jusqu'au niveau 10 et ils évoluent.",
  "Teclas 1, 2 y 3. Ofensiva: más daño y más riesgo. Equilibrada: neutra. Defensiva: menos daño recibido. Toca una:": "Touches 1, 2 et 3. Offensive : plus de dégâts et plus de risques. Équilibrée : neutre. Défensive : moins de dégâts subis. Touches-en une :",
  "Objetos y experiencia": "Objets et expérience",
  "Chispa verde, balón azul y rayo dorado dan experiencia (de menos a más). La comida cura y los objetos especiales te ayudan un rato.": "L'étincelle verte, le ballon bleu et l'éclair doré donnent de l'expérience (du moins au plus). La nourriture soigne et les objets spéciaux t'aident un moment.",
  "Fichajes y fichas": "Recrues et jetons",
