  "{tokens} fichas · {x1} ◉ si jugaste esa semana": "{tokens} jetons · {x1} ◉ si tu as joué cette semaine-là",
  "Semana {x1}": "Semaine {x1}",
  "{x1}El bando es para toda la temporada y no se puede cambiar. Para que la lucha sea justa, el bando que vaya por delante en miembros no admite a nadie más hasta que el otro lo alcance. Cuentan las victorias de partidas normales (sin cooperativo, Road, clan ni entrenamiento).": "{x1}Le camp est choisi pour toute la saison et ne peut pas être changé. Pour que le combat reste équitable, le camp en tête en nombre de membres n'accepte plus personne tant que l'autre ne l'a pas rattrapé. Les victoires en parties normales comptent (hors coopératif, Road, clan et entraînement).",
  "Road to Fútbol Frontier: ahora Jaden sale a las 3 victorias en Máxima y otra copia cada 3. Por tus victorias recibes {x1}.": "Road to Football Frontier : Jaden arrive maintenant après 3 victoires en Maximale, puis une autre copie toutes les 3. Pour tes victoires, tu reçois {x1}.",
  "{x1} repeticiones borradas": "{x1} replays supprimés",
  "{rowsLength} repeticiones · {x1} en total. Cada jugador guarda sus 3 últimas y las de sus marcas del ranking.": "{rowsLength} replays · {x1} au total. Chaque joueur garde ses 3 derniers et ceux de ses records du classement.",
  "{x1} · Nv {level}": "{x1} · Nv {level}",
