  "{x1} de {x2}": "{x1} sur {x2}",
  "Sin vínculo especial con {pName}. Un compañero de historia, familia o técnica conjunta daría {x1}%.": "Aucun lien spécial avec {pName}. Un coéquipier d'histoire, un membre de la famille ou une technique conjointe donnerait {x1} %.",
  "Bonificación = estadística del Aura × {x1}%, redondeada. Lo propio sigue en 99 como máximo; con el Aura, hasta {EFFECTIVE_STAT_MAX}.": "Bonus = stat de l'Aura × {x1} %, arrondi. Les stats propres restent à 99 maximum ; avec l'Aura, jusqu'à {EFFECTIVE_STAT_MAX}.",
  "{x1} · {x2} · poder {power}": "{x1} · {x2} · puissance {power}",
  "La primera empieza la partida en una ranura extra de Aura; la segunda puede aprenderse al subir de nivel. Golpean al {x1}% (son una técnica activa de más). No sustituyen a las suyas y desaparecen si quitas el Aura.": "La première commence la partie dans un emplacement d'Aura en plus ; la seconde peut s'apprendre en montant de niveau. Elles frappent à {x1} % (c'est une technique active de plus). Elles ne remplacent pas les siennes et disparaissent si tu retires l'Aura.",
  "{x1} Afinidad de {x2}": "{x1} Affinité {x2}",
  "Las técnicas de {pName} de elemento {x1} (también las heredadas) hacen <b>+{x2}%</b> de daño. {pName} sigue siendo de {x3} para todo lo demás.": "Les techniques {x1} de {pName} (héritées comprises) infligent <b>+{x2} %</b> de dégâts. {pName} reste {x3} pour tout le reste.",
  "y {x1} más · recógelos en Recompensas": "et {x1} de plus · récupère-les dans Récompenses",
