  "{x1} y {x2} equipo(s) más": "{x1} et {x2} équipe(s) de plus",
  "Jugadores de Fichatrón / Ojeadores: {x1} de {scoutsLength}. No pertenecen a un equipo de la historia, pero juegan igual que los demás.": "Joueurs du Recrutotron / Recruteurs : {x1} sur {scoutsLength}. Ils n'appartiennent à aucune équipe de l'histoire, mais jouent comme les autres.",
