  "Duplicado de {x1}": "Doublon de {x1}",
  "{offersLength} ofertas · {x1}": "{offersLength} offres · {x1}",
  "EVENTO · TERMINA EN {x1}": "ÉVÉNEMENT · SE TERMINE DANS {x1}",
  "{x1} ◉ la tirada · Míticos al 3%": "{x1} ◉ le tirage · Mythiques à 3 %",
  "DÍA {x1}{x2}": "JOUR {x1}{x2}",
  "{x1} Si te saltas días no pierdes nada: el pase te espera.": "{x1} Si tu sautes des jours, tu ne perds rien : le passe t'attend.",
  "{x1}{x2} · tras el día {PASSLength} empieza un ciclo nuevo": "{x1}{x2} · après le jour {PASSLength}, un nouveau cycle commence",
  "{x1} <b>{x2}</b>, y si llevas {min} o más jugadores de ese equipo en el campo, «Química de club»: +{x3}% de daño.": "{x1} <b>{x2}</b>, et si tu as {min} joueurs ou plus de cette équipe sur le terrain, « Alchimie du club » : +{x3} % de dégâts.",
  "Posiciones distintas ({x1} / {x2}): la comparación es orientativa.": "Postes différents ({x1} / {x2}) : la comparaison est indicative.",
  "Comparten equipo: {x1} (química de club con 3 o más en el campo).": "Ils partagent une équipe : {x1} (alchimie du club avec 3 ou plus sur le terrain).",
  "Faltan duplicados: {x1} más": "Doublons manquants : {x1} de plus",
  "Faltan {x1} monedas": "Il manque {x1} pièces",
  "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · daño ×{toFixed} · vida ×{toFixed2} · duplicados libres {sparesOf}": "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · dégâts ×{toFixed} · vie ×{toFixed2} · doublons libres {sparesOf}",
  "✦ Elige {x1} de límite (+{STAR_CAP_STEP})": "✦ Choisis {x1} de limite (+{STAR_CAP_STEP})",
  "Toca una estadística por cada estrella: su límite sube +{STAR_CAP_STEP}. Puedes repetir la misma.{x1}": "Touche une statistique pour chaque étoile : sa limite monte de +{STAR_CAP_STEP}. Tu peux répéter la même.{x1}",
  "{pName}: {done} {x1} de límite": "{pName} : {done} {x1} de limite",
  "★ Estrella de héroe ({sparesOf}/{x1})": "★ Étoile de héros ({sparesOf}/{x1})",
  "▲ Ascensión ({sparesOf}/{x1})": "▲ Ascension ({sparesOf}/{x1})",
  "Maestría {x1}/{MASTERY_USESLength} · +{x2}% daño · {x3} usos": "Maîtrise {x1}/{MASTERY_USESLength} · +{x2} % de dégâts · {x3} utilisations",
  "Estadísticas · media {statMean}{x1}": "Statistiques · moyenne {statMean}{x1}",
  "(con su Aura {aeName}; propia {x1})": "(avec son Aura {aeName} ; propre {x1})",
  "COLABORACIÓN · TERMINA EN {x1}": "COLLAB · SE TERMINE DANS {x1}",
  "★ Destacada hoy: Épico ×{x1} · Legendario, Mítico y Leyenda ×{x2}": "★ À la une aujourd'hui : Épique ×{x1} · Légendaire, Mythique et Légende ×{x2}",
  "{x1}Precio y reglas": "{x1}Prix et règles",
  "Los futbolistas especiales solo salen aquí, con {x1} Comunes, Raros y Épicos de relleno. Se paga con fichas de evento: cada partida en Rango S o X te da tantas como fichas normales mientras dura el evento.": "Les joueurs spéciaux ne sortent qu'ici, avec {x1} Communs, Rares et Épiques en complément. Ça se paie en jetons d'événement : chaque partie en Rang S ou X t'en donne autant que de jetons normaux pendant l'événement.",
  "{x1}Tus {unit}": "{x1}Tes {unit}",
  "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (diez ×10 de golpe, un Épico o mejor asegurado en cada diez). {x4}{x5}": "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (dix ×10 d'un coup, un Épique ou mieux garanti tous les dix). {x4}{x5}",
  "Te llega para {x1} tirada(s).": "Ça te suffit pour {x1} tirage(s).",
  "{x1}Cómo conseguir fichas": "{x1}Comment obtenir des jetons",
  "{x1}Nuevo, duplicado y ascensión": "{x1}Nouveau, doublon et ascension",
  "(hasta {MAX_STARS}): se compran con monedas en su ficha (10.000, 20.000… 50.000). Cada una da +{x1}% daño, +{x2}% vida y +5 al límite de la estadística que elijas. Los HÉROES y Campeones tienen 3 estrellas extra (100.000, 110.000 y 120.000).": "(jusqu'à {MAX_STARS}) : elles s'achètent avec des pièces sur sa fiche (10 000, 20 000… 50 000). Chacune donne +{x1} % de dégâts, +{x2} % de vie et +5 à la limite de la statistique de ton choix. Les HÉROS et les Champions ont 3 étoiles bonus (100 000, 110 000 et 120 000).",
  "{x1}Probabilidades": "{x1}Probabilités",
  "{x1}: sin futbolistas por ahora; su probabilidad pasa a la rareza inferior.": "{x1} : aucun joueur pour l'instant ; sa probabilité passe à la rareté inférieure.",
  "{x1}Últimas tiradas": "{x1}Derniers tirages",
