  "RECLAMAR TODO{x1}": "TOUT RÉCLAMER{x1}",
  "Manual {lv}/{MAX_TECH_BOOST} · +{x1}% daño": "Manuel {lv}/{MAX_TECH_BOOST} · +{x1} % de dégâts",
  "Aparece sola en partida a partir del nivel {x1}; comprándola, desde el 1.": "Elle apparaît toute seule en partie à partir du niveau {x1} ; en l'achetant, dès le niveau 1.",
  "{x1}Tu plantilla": "{x1}Ton effectif",
  "{x1} · {techniquesLength} técnicas": "{x1} · {techniquesLength} techniques",
  "Máquina de cápsulas: gráficos de Inazuma Eleven 3 (LEVEL-5), hoja publicada en {x1}, ripeada por Avegaille.": "Machine à capsules : graphismes d'Inazuma Eleven 3 (LEVEL-5), planche publiée sur {x1}, extraite par Avegaille.",
  "Nombres en español e inglés de parte de las técnicas: {x1} (Fandom), contenido bajo {x2}.": "Noms espagnols et anglais d'une partie des techniques : {x1} (Fandom), contenu sous {x2}.",
  "Motor: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Herramienta: {x3} (MIT).": "Moteur : {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Outil : {x3} (MIT).",
  "Fuente: Press Start 2P © The Press Start 2P Project Authors ({x1}), vía Fontsource.": "Police : Press Start 2P © The Press Start 2P Project Authors ({x1}), via Fontsource.",
  "Ahora suena: {x1}. Por defecto suena la música de Inazuma Eleven exportada de tu copia. «Generada» usa temas creados para este proyecto.": "En cours de lecture : {x1}. Par défaut, c'est la musique d'Inazuma Eleven exportée de ta copie qui joue. « Générée » utilise des morceaux créés pour ce projet.",
  "Vuelves a empezar como un jugador nuevo{x1}. No es lo mismo que eliminar la cuenta.": "Tu recommences comme un nouveau joueur{x1}. Ce n'est pas la même chose que supprimer le compte.",
  "Tu progreso se guarda en este navegador.{x1}": "Ta progression est sauvegardée dans ce navigateur.{x1}",
