  "{got}/{itemsLength} desbloqueados{x1}": "{got}/{itemsLength} débloqués{x1}",
  "{x1}Técnicas combinadas": "{x1}Techniques combinées",
  "Falta: {x1}": "Manque : {x1}",
  "Récord actual: {x1} en supervivencia infinita. Lo ganado se conserva al caer o al retirarte desde Pausa.": "Record actuel : {x1} en survie infinie. Ce que tu gagnes est conservé si tu tombes ou si tu abandonnes depuis Pause.",
