  "Tiempo extra {x1} · Fase alcanzada: {x2} · Jefes adicionales: {x3}": "Temps additionnel {x1} · Phase atteinte : {x2} · Boss supplémentaires : {x3}",
  "Recompensas del infinito: {x1} monedas y {x2} fichas{x3}": "Récompenses de l'infini : {x1} pièces et {x2} jetons{x3}",
