  "¡Tienes {pending} {x1} por cobrar!": "Tu as {pending} {x1} à récupérer !",
  "elegido: toca una fila": "choisi : touche une ligne",
  "Es el último nivel: Campeón++": "C'est le dernier niveau : Champion++",
  "Marco dorado e insignia HÉROE en la colección": "Cadre doré et insigne HÉROS dans la collection",
