  "con R": "avec R",
  "Capitán: <b>{capName}</b>": "Capitaine : <b>{capName}</b>",
  "Esperando a que <b>{partner}</b> elija la arena y empiece…": "En attente que <b>{partner}</b> choisisse l'arène et lance la partie…",
  "Mis depósitos": "Mes dépôts",
  ": otro dispositivo guardó una versión más nueva": " : un autre appareil a sauvegardé une version plus récente",
  "Próximo gran premio: <b>{label}</b> · nivel {x1} {x2} · faltan {x3}": "Prochaine grande récompense : <b>{label}</b> · niveau {x1} {x2} · encore {x3}",
  "Ver el Sector": "Voir le Secteur",
  "El fútbol necesita orden. A partir de hoy, el Sector Quinto decide cómo se juega cada partido.": "Le football a besoin d'ordre. À partir d'aujourd'hui, le Cinquième Secteur décide comment se joue chaque match.",
  "Únete a nosotros… o intenta resistir. Cada semana veremos qué bando juega mejor.": "Rejoins-nous… ou essaie de résister. Chaque semaine, nous verrons quel camp joue le mieux.",
  "Bienvenido al Sector Quinto. Aquí el fútbol se juega como yo digo.": "Bienvenue au Cinquième Secteur. Ici, le football se joue comme je le dis.",
  "Acata mis decretos y tu bando ganará.": "Obéis à mes décrets et ton camp gagnera.",
  "La Resistencia… Veremos cuánto aguanta vuestro viento.": "La Résistance… Nous verrons combien de temps votre vent tiendra.",
  "Rebélate si quieres: el Sector Quinto también sabe jugar duro.": "Rebelle-toi si tu veux : le Cinquième Secteur sait aussi jouer dur.",
  "¡Llega {eName}!": "{eName} arrive !",
  "{x1} · {x2} rivales · Nv {level}": "{x1} · {x2} adversaires · Nv {level}",
  "sus estadísticas (Aura legendaria)": "ses statistiques (Aura légendaire)",
  "Cada plaza de tu equipo tiene ahora una <b>{x1}</b> {x2} <b>{x3}</b>. Ahí pones a otro futbolista de tu colección para que apoye al de la plaza. El Aura no juega: lo potencia.": "Chaque place de ton équipe a maintenant une <b>{x1}</b> {x2} <b>{x3}</b>. Tu y mets un autre joueur de ta collection pour soutenir celui de la place. L'Aura ne joue pas : elle le renforce.",
  "Solo pueden ser Aura los <b>Legendarios, Míticos y Leyendas</b>.": "Seuls les <b>Légendaires, Mythiques et Légendes</b> peuvent être une Aura.",
  "Una por futbolista. No se gasta nada: tu colección no cambia.": "Une par joueur. Rien n'est dépensé : ta collection ne change pas.",
  "El Aura suma el <b>{x1}%</b> {x2} <b>{x3}</b> a las mismas del portador.": "L'Aura ajoute <b>{x1} %</b> {x2} <b>{x3}</b> aux mêmes stats du porteur.",
  "Ejemplo: Tiro 90 + Aura con Tiro 95 » 90 + 14 = <b>104</b>.": "Exemple : Frappe 90 + Aura avec Frappe 95 » 90 + 14 = <b>104</b>.",
  "Lo propio sigue en 99 como máximo; con el Aura, hasta <b>120</b>, y en el combate se nota.": "Les stats propres restent à 99 maximum ; avec l'Aura, jusqu'à <b>120</b>, et ça se sent en combat.",
  "En el radar, lo que aporta el Aura se ve en <b style=\"color:#7ff6ff\">cian</b>.": "Sur le radar, ce qu'apporte l'Aura apparaît en <b style=\"color:#7ff6ff\">cyan</b>.",
  "Si los dos tienen historia (técnica conjunta, amistad, familia o rivalidad), el Aura da el <b>{x1}%</b>{x2} <b>♥</b>.": "Si les deux partagent une histoire (technique conjointe, amitié, famille ou rivalité), l'Aura donne <b>{x1} %</b>{x2} <b>♥</b>.",
  "Axel y Shawn, Mark y Nathan, Jude y Celia, Arion y Riccardo...": "Axel et Shawn, Mark et Nathan, Jude et Celia, Arion et Riccardo...",
  "Estar en el mismo equipo no basta.": "Être dans la même équipe ne suffit pas.",
  "El portador hereda <b>{x1}</b> del Aura: una empieza la partida en una ranura extra y la otra llega como carta al subir de nivel. No sustituyen a las suyas.": "Le porteur hérite de <b>{x1}</b> de l'Aura : l'une commence la partie dans un emplacement en plus et l'autre arrive en carte en montant de niveau. Elles ne remplacent pas les siennes.",
  "Sus técnicas del elemento del Aura hacen <b>+{x1}%</b>.": "Ses techniques de l'élément de l'Aura infligent <b>+{x1} %</b>.",
  "Con el Aura puede lanzar <b>{x1}</b>: Axel con Shawn de Aura, Fuego cruzado.": "Avec l'Aura, il peut lancer <b>{x1}</b> : Axel avec Shawn en Aura, Feu Glacé.",
  "Cómo equiparla:": "Comment l'équiper :",
  "toca «+ AURA» y elige en tu colección, o arrastra la carta encima.": "touche « + AURA » et choisis dans ta collection, ou fais glisser la carte dessus.",
