  "Mark adulto entrena al Raimon de Arion y le enseña a amar el fútbol.": "Mark adulte entraîne le Raimon d'Arion et lui apprend à aimer le football.",
  "Darren admira a Mark y hereda su Mano mágica como portero del Raimon.": "Darren admire Mark et hérite de sa Main Magique comme gardien de Raimon.",
