  "LA GACETA {x1}": "LA GAZETTE {x1}",
  "Versión de pruebas del cooperativo: puede fallar. Tu partida es la misma que en la web normal.": "Version de test du coopératif : elle peut planter. Ta sauvegarde est la même que sur le site normal.",
  "PRUEBAS · pre-2.0": "TEST · pré-2.0",
  "Cargando futbolistas…": "Chargement des joueurs…",
  "No se pudieron cargar los datos del juego. Si el problema sigue, esta versión puede no incluir sus recursos.": "Impossible de charger les données du jeu. Si le problème persiste, cette version n'inclut peut-être pas ses ressources.",
  "Preparando caras y objetos…": "Préparation des visages et des objets…",
  "Abriendo el vestuario…": "Ouverture du vestiaire…",
  "¡Listo!": "Prêt !",
  "InaZurvivors 2.3 — Ya en inglés": "InaZurvivors 2.3 — Maintenant en anglais",
  "InaZurvivors, now in English": "InaZurvivors, maintenant en anglais",
  "El juego entero se puede jugar en inglés: menús, partidas, datos, noticias y todo el historial de versiones. Si tu navegador está en inglés se abre solo en inglés; si no, sigue en español.": "Tout le jeu peut se jouer en anglais : menus, parties, données, actualités et tout l'historique des versions. Si ton navigateur est en anglais, il s'ouvre en anglais tout seul ; sinon, il reste en espagnol.",
  "Español o inglés": "Espagnol ou anglais",
  "Elige el idioma en Ajustes > Idioma, o déjalo en «Automático» para que siga al navegador. Al cambiarlo, el juego se recarga en el idioma nuevo y tu partida no cambia.": "Choisis la langue dans Paramètres > Langue, ou laisse « Automatique » pour suivre ton navigateur. Quand tu la changes, le jeu se recharge dans la nouvelle langue et ta sauvegarde reste la même.",
  "Nombres oficiales": "Noms officiels",
  "En inglés, las supertécnicas y las técnicas combinadas llevan su nombre del doblaje oficial (Fire Tornado, God Hand, Crossfire…), y los elementos son Fire, Wind, Wood y Earth.": "En anglais, les supertechniques et les techniques combinées portent leurs noms officiels du doublage (Fire Tornado, God Hand, Crossfire…), et les éléments sont Fire, Wind, Wood et Earth.",
  "Noticias en los dos idiomas": "Les actualités dans les deux langues",
  "Las noticias y todas las versiones desde la v1.0 se pueden leer en inglés.": "Les actualités et chaque version depuis la v1.0 peuvent se lire en anglais.",
  "Números a su manera": "Les chiffres à leur façon",
  "En inglés, las cifras y las fechas salen con el formato inglés (1,000 monedas, 0.5 %).": "En anglais, les nombres et les dates utilisent le format anglais (1,000 coins, 0.5%).",
  "Abre Ajustes y mira la nueva opción Idioma.": "Ouvre Paramètres et regarde la nouvelle option Langue.",
  "Pásale el juego a tus amigos que no hablan español.": "Partage le jeu avec tes amis qui ne parlent pas espagnol.",
  "Muévete con el joystick y acércate a alguien para ver su ficha; tócala para abrir su perfil.": "Déplace-toi avec le joystick et approche-toi de quelqu'un pour voir sa fiche ; touche-la pour ouvrir son profil.",
  "Muévete con WASD o flechas y pasa el ratón por encima de alguien para ver su ficha; haz clic para abrir su perfil.": "Déplace-toi avec ZQSD/WASD ou les flèches et passe la souris sur quelqu'un pour voir sa fiche ; clique pour ouvrir son profil.",
  "Top 3": "Top 3",
  "♥ AMIGO": "♥ AMI",
  "Equipación: {x1}": "Tenue : {x1}",
  "Toca para ver su perfil": "Touche pour voir son profil",
  "Clic para ver su perfil": "Clique pour voir son profil",
  "Sala de jugadores renovada": "Salon des joueurs renouvelé",
  "Cada jugador lleva su equipación, tus amigos salen en verde, el top 3 con su corona y, sobre el nombre, el escudo de su clan y su bando. Haz clic (o toca su ficha) para abrir su perfil.": "Chaque joueur porte sa tenue, tes amis apparaissent en vert, le top 3 avec sa couronne et, au-dessus du nom, l'écusson de son clan et son camp. Clique (ou touche sa carte) pour ouvrir son profil.",
  "¿Padre e hijo? Jaden lleva el apellido de Mark adulto y juega con su mismo corazón. Nadie lo ha confirmado.": "Père et fils ? Jaden porte le nom de famille de Mark adulte et joue avec le même cœur. Personne ne l'a confirmé.",
  "Los Evans: el cuaderno de entrenamiento de David llega hasta Jaden.": "Les Evans : le carnet d'entraînement de David arrive jusqu'à Jaden.",
  "Silvia lo cuida como cuidó al Raimon de Mark… y dicen que Jaden tiene su misma mirada. ¿Será su madre?": "Silvia veille sur lui comme elle veillait sur le Raimon de Mark… et on dit que Jaden a ses yeux. Serait-elle sa mère ?",
  "Vibración (móvil)": "Vibration (mobile)",
  "Activada": "Activée",
  "Desactivada": "Désactivée",
  "Más vivo en el móvil": "Plus vivant sur mobile",
  "El móvil vibra al recibir un golpe, al subir de nivel, con las definitivas, al llegar el jefe y al fichar un Legendario o mejor (se quita en Ajustes). Los botones responden al tocarlos y los avisos ya no tapan la partida.": "Ton téléphone vibre quand tu prends un coup, montes de niveau, lances des ultimes, quand le boss arrive et quand tu recrutes un Légendaire ou mieux (désactivable dans Paramètres). Les boutons réagissent au toucher et les avis ne cachent plus la partie.",
  "la Llave dorada del pase": "la Clé dorée du passe",
  "{n} futbolistas": "{n} joueurs",
  "Creadores de contenido: banner y marco propios, 1.500 fichas de colaboración, 3.000 fichas, la Llave dorada, los 7 del Banner de agradecimiento, 300.000 monedas y 9 Fichas EG": "Créateurs de contenu : leur propre bannière et cadre, 1 500 jetons de collab, 3 000 jetons, la Clé dorée, les 7 de la Bannière de remerciement, 300 000 pièces et 9 Jetons EG",
  "Creador de contenido": "Créateur de contenu",
  "Código de creadores de contenido": "Code créateur de contenu",
  "Grabas, editas y subes: InaZurvivors llega más lejos gracias a ti.": "Tu enregistres, tu montes et tu publies : InaZurvivors va plus loin grâce à toi.",
  "Marco de Creador": "Cadre de Créateur",
  "Un botón de play con alas: el marco de quien graba InaZurvivors.": "Un bouton play avec des ailes : le cadre de ceux qui enregistrent InaZurvivors.",
  "Tu última partida se cortó a los {x1}: aquí tienes lo que llevabas ganado.": "Ta dernière partie a été coupée à {x1} : voici ce que tu avais gagné jusque-là.",
  "Teclados AZERTY": "Claviers AZERTY",
  "El movimiento va por la posición de las teclas y no por la letra: en un teclado francés te mueves con ZQSD.": "Le déplacement suit la position des touches, pas leur lettre : sur un clavier français, tu te déplaces avec ZQSD.",
  "¡RÉCORD!": "RECORD !",
  "Eliminaciones": "Éliminations",
